values ('ap_statistics', 1, '1.10', array['1.10']::text[], 'list_sequence', 'Three components of an investigative question', 'An investigative question has three components: one guiding data collection, one guiding the analysis choice, and one indicating the type of conclusion.', '[{"label": "First component", "meaning": "Guides data collection and is phrased in terms of the variable(s) of interest"}, {"label": "Second component", "meaning": "Guides the data analysis choice: for a hypothesis test, make clear the parameter and the direction of the alternative; for a confidence interval, make clear the parameter and the goal of estimating it within a range of values"}, {"label": "Third component", "meaning": "Indicates the type(s) of conclusion applicable: the population to which conclusions apply and, for an experiment with random assignment, a cause-and-effect conclusion"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-r2-004; ced=1.10.A.1, 1.10.A.2, 1.10.A.3')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_statistics', 1, '1.10', array['1.10', '1.13']::text[], 'convention', 'When generalization to a population is appropriate', 'If units are randomly selected from a population, generalize to that entire population; if they are not randomly selected (deliberately chosen or volunteers), generalize only to a population of individuals similar to those in the study.', '[]'::jsonb, NULL, 'To justify generalizing, cite random selection of the sample; random assignment supports cause-and-effect conclusions, not generalization.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-r2-008; ced=1.10.E.2 and 1.10.E.4')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
insert into app.unit_reference_entries (subject_key, unit_number, owner_topic_code, topic_codes, kind, title, body, items, visual_asset_ref, caution, status, source_note)
values ('ap_statistics', 1, '1.11', array['1.11']::text[], 'vocabulary', 'Cluster random sample', 'The population is divided into clusters, each ideally mirroring the population''s heterogeneity; an SRS of clusters is selected and data are collected from all units in each selected cluster.', '[]'::jsonb, NULL, 'Cluster sampling includes every unit in the chosen clusters, unlike stratified sampling which samples within every stratum.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-064; ced=1.11.A.5')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
