values ('ap_statistics', 1, '1.11', array['1.11']::text[], 'list_sequence', 'Random sampling methods named in the CED', 'The four random sampling designs students must identify and justify.', '[{"label": "Simple random sample", "meaning": "every sample of size n equally likely"}, {"label": "Stratified random sample", "meaning": "SRS within each of the non-overlapping strata"}, {"label": "Cluster random sample", "meaning": "SRS of clusters, then all units in chosen clusters"}, {"label": "Systematic random sample", "meaning": "random start, then fixed periodic interval"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-066; ced=1.11.A.3–1.11.A.6; 1.11.B.1')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
