values ('ap_statistics', 1, '1.11', array['1.11']::text[], 'vocabulary', 'Sampling with replacement', 'A strategy in which a unit is returned to the population before later selections, so it can be selected more than once.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-061; ced=1.11.A.2')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
