values ('ap_statistics', 1, '1.11', array['1.11']::text[], 'vocabulary', 'Sampling without replacement', 'A strategy in which a unit can be selected only once, because it is not returned to the population before later selections.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-060; ced=1.11.A.1')
