values ('ap_statistics', 1, '1.11', array['1.11']::text[], 'vocabulary', 'Stratified random sample', 'The population is divided into non-overlapping homogeneous groups (strata), an SRS is taken within each stratum, and the selected individuals are combined into one sample.', '[]'::jsonb, NULL, 'Stratified samples some units from every stratum; cluster samples all units from only some clusters.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-063; ced=1.11.A.4')
