values ('ap_statistics', 1, '1.12', array['1.12']::text[], 'list_sequence', 'Types of sampling bias', 'Voluntary response, undercoverage, nonresponse, and response bias.', '[{"label": "Voluntary response bias", "meaning": "may occur when a sample consists entirely of volunteers"}, {"label": "Undercoverage bias", "meaning": "sampling method fails to include part of the population or makes part less likely to be selected"}, {"label": "Nonresponse bias", "meaning": "failure to obtain responses from some chosen individuals, who may differ significantly from respondents in important ways"}, {"label": "Response bias", "meaning": "responses or measurements tend to differ from the true value in one direction, e.g., confusing or leading questions (question wording bias) or self-reported responses"}]'::jsonb, NULL, 'For nonresponse bias, support the claim by stating whether the sample result is likely too high or too low compared with the population value; use the specific bias name rather than confounding or small sample size.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-068; ced=1.12.A.2, 1.12.A.3, 1.12.A.4, 1.12.A.5')
on conflict (subject_key, owner_topic_code, kind, title) do nothing;
