values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'list_sequence', 'Elements of a well-designed experiment', 'A well-designed experiment includes comparison of treatment groups, random assignment, replication, and direct control of extraneous variation.', '[{"label": "Comparisons", "meaning": "Comparisons of at least two treatment groups, one of which could be a control group"}, {"label": "Random assignment", "meaning": "Random assignment of treatments to experimental units"}, {"label": "Replication", "meaning": "More than one experimental unit is assigned to each treatment"}, {"label": "Direct control", "meaning": "Direct control of potential extraneous sources of variation in the response, keeping their settings the same from unit to unit"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-r2-009; ced=1.13.A.1.i–iv')
