values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'vocabulary', 'Extraneous source of variation', 'A variable known or believed to affect the response but that is not an explanatory variable being studied.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-074; ced=1.13.A.6')
