values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'vocabulary', 'Matched pairs design', 'A randomized block design with only two treatments: units are paired by matching on extraneous variables and treatments are randomly assigned within each pair, or each unit gets both treatments in a randomized order.', '[]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-079; ced=1.13.B.4')
