values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'vocabulary', 'Placebo effect', 'The difference between the average response to a placebo and the average response to no treatment.', '[]'::jsonb, NULL, 'The placebo effect is not just "a fake treatment"; it is the difference between average placebo response and average no-treatment response.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-072; ced=1.13.A.3')
