values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'vocabulary', 'Randomized block design', 'Experimental units are first grouped into blocks that are homogeneous on a blocking variable, then treatments are randomly assigned within each block so all treatments occur in every block.', '[]'::jsonb, NULL, 'Blocking separates variation caused by the blocking variable, allowing more precise treatment comparisons; random assignment still occurs within each block.', 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-078; ced=1.13.B.2, 1.13.B.3')
