values ('ap_statistics', 1, '1.13', array['1.13']::text[], 'list_sequence', 'Single-blind vs. double-blind', 'Blinding is defined by who knows which treatment each participant receives.', '[{"label": "Single-blind (single-masked)", "meaning": "participants do not know their treatment but the research team members who interact with them do, or vice versa"}, {"label": "Double-blind (double-masked)", "meaning": "neither participants nor the research team members who interact with them know the treatment"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=task0067-reference-pilot-2026-10-09; candidate=ap_statistics-u1-073; ced=1.13.A.4, 1.13.A.5')
